function deriveSealedDisplayType(item){
  // Collectibles short-circuit: their names are card names ("Tinker Bell",
  // "The First Chapter") and would otherwise fall through the keyword rules
  // below into whatever they happen to contain.
  if(item.is_collectible) return item.product_type === "Pin" ? "Pins" : "Lore Counters";
  const name = (item.name || "").toLowerCase();
  // Cases & displays. Booster-box cases (the popular ones) get their own
  // "Cases" section; every other case/display lands in "Other Displays /
  // Cases". " case" needs a leading space to dodge mid-word false positives;
  // "display" matches "Starter Deck Display" and similar.
  if(name.includes("booster box case")) return "Cases";
  if(name.includes(" case") || / display( |$)/.test(name)) return "Other Displays / Cases";
  // Pack sub-variants: basic vs sleeved. Art-bundle SKUs are filtered out
  // upstream (isHiddenSealedListing) so they never reach here.
  if(item.product_type === "Booster Pack"){
    if(name.includes("sleeved")) return "Sleeved Booster Packs";
    return "Booster Packs";
  }
  // Special-edition "Collection Starter Set" and "Starter Blister Bundle"
  // SKUs aren't competitive starter decks — they're sealed multi-pack
  // collectibles. Surface them under Bundles instead.
  if(item.product_type === "Starter Deck"){
    if(name.includes("collection starter") || name.includes("starter blister")){
      return "Bundles";
    }
  }
  // The catch-all "Sealed" product_type holds only D23 collections (→
  // Collector's Edition) and the Gateway box (→ Quests). Reroute both so the
  // generic "Sealed" section disappears entirely.
  if(item.product_type === "Sealed"){
    if(name.includes("d23")) return "Collector's Edition";
    if(name.includes("gateway")) return "Quests";
  }
  return SEALED_DISPLAY_TYPE_FOR[item.product_type] || item.product_type || "Other Sealed";
}
